import xarray as xr
import numpy as np
from xarray.core.indexes import Index
from xarray.core.variable import Variable

class CustomIndex(Index):
    def __init__(self, x, y):
        self.x = x
        self.y = y

    @classmethod
    def from_variables(cls, variables, options=None):
        # Expecting variables to have 'x' and 'y'
        x = variables['x'].values
        y = variables['y'].values
        return cls(x, y)

    def create_variables(self, variables=None):
        # Return x, y and a new variable 'z'
        # In a real scenario, z would be computed from x and y
        # For simplicity, we just return some dummy variables
        # We need to return Variable objects

        # We can use the variables passed in to get the dimension and metadata
        x_var = variables['x']
        y_var = variables['y']

        # Create a new variable 'z' that depends on 'x' and 'y'
        # For the sake of the test, let's just make it a coordinate
        z_values = x_var.values + y_var.values
        z_var = Variable("z", z_values, attrs={"description": "computed z"})

        return {"x": x_var, "y": y_var, "z": z_var}

def test_custom_index_creates_new_variable():
    ds = xr.Dataset(
        coords={
            "x": [1, 2],
            "y": [3, 4],
        },
        data_vars={"foo": (("x", "y"), np.random.rand(2, 2))}
    )

    # Set xindex using 'x' and 'y'
    # Note: set_xindex expects coord_names to be the dimensions of the index
    # In this case, the index is 1D but depends on two coords? 
    # Wait, if I use two coords, it's usually a MultiIndex.
    # Let's make it simpler.

    ds = xr.Dataset(
        coords={
            "time": [1, 2],
            "step": [3, 4],
        },
        data_vars={"foo": (("time",), [1, 2])}
    )

    # We want an index that is associated with 'time' and 'step'
    # and creates 'valid_time'.
    # But set_xindex usually associates the index with a single dimension.
    # If coord_names is a list, it's a multi-index on a single dimension.

    # Let's try to reproduce the issue as described:
    # "I'd like the index to return a valid_time = time + step and for ForecastIndex to be associated with time, step, and valid_time."

    # If we use set_xindex(['time', 'step']), it will create a multi-index on a new dimension (usually the name of the first coord or a combined name).

    # Let's see how set_xindex handles multiple coords.
    # If len(coord_names) > 1, it's a MultiIndex.

    # Let's use a simpler example.
    ds = xr.Dataset(
        coords={
            "x": [1, 2],
            "y": [3, 4],
        },
        data_vars={"foo": (("x",), [1, 2])}
    )

    # This will fail because 'y' is not a dimension of 'foo' and not a dimension of the dataset.
    # Let's make 'x' and 'y' both dimensions.
    ds = xr.Dataset(
        coords={
            "x": [1, 2],
            "y": [3, 4],
        },
        data_vars={"foo": (("x", "y"), np.random.rand(2, 2))}
    )

    # We want to set an index on 'x' that also creates 'z'.
    class SimpleCustomIndex(Index):
        def __init__(self, x):
            self.x = x
        @classmethod
        def from_variables(cls, variables, options=None):
            return cls(variables['x'].values)
        def create_variables(self, variables=None):
            x_var = variables['x']
            z_var = Variable("z", x_var.values * 2)
            return {"x": x_var, "z": z_var}

    ds_indexed = ds.set_xindex("x", index_cls=SimpleCustomIndex)

    if "z" not in ds_indexed.coords:
        print("Bug: 'z' coordinate was not created by the index")
        exit(1)
    else:
        print("Success: 'z' coordinate was created")
        exit(0)

if __name__ == "__main__":
    test_custom_index_creates_new_variable()
